#!/usr/bin/env bash
# Source the environment generated by setup; also accepts an already configured shell.
_verusseek_env_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
if [[ -r "$_verusseek_env_root/.local/env.sh" ]]; then
    source "$_verusseek_env_root/.local/env.sh"
fi
if ! command -v cargo >/dev/null 2>&1; then
    echo 'Run: bash scripts/setup.sh' >&2
    unset _verusseek_env_root
    return 1
fi
if [[ -z "${VERUS_PATH:-}" ]]; then
    export VERUS_PATH="$(command -v verus || true)"
fi
if [[ ! -x "${VERUS_PATH:-}" ]] && ! command -v "${VERUS_PATH:-verus}" >/dev/null 2>&1; then
    echo 'Run: bash scripts/setup.sh (or set VERUS_PATH to an installed Verus)' >&2
    unset _verusseek_env_root
    return 1
fi
unset _verusseek_env_root
